def flaky_report(run_results, min_rate):
    rates = {cid: round(sum(r) / len(r), 2) for cid, r in run_results.items()}
    failing = sorted(cid for cid, rate in rates.items() if rate < min_rate)
    all_runs = [x for r in run_results.values() for x in r]
    overall = round(sum(all_runs) / len(all_runs), 2)
    return {'rates': rates, 'failing': failing, 'overall': overall}
